import type { Context } from "hono";
import { streamSSE } from "hono/streaming";
import { sessions } from "../manager/SessionManager";

/** GET /photo-stream — SSE for real-time photo updates */
export function photoStream(c: Context) {
  const userId = c.req.query("userId");
  if (!userId) return c.json({ error: "userId is required" }, 400);

  const user = sessions.get(userId);
  if (!user) return c.json({ error: `No user for ${userId}` }, 404);

  console.log(`[SSE Photo] Client connected for user: ${userId}`);

  return streamSSE(c, async (stream) => {
    const client = {
      write: (data: string) => stream.writeSSE({ data }),
      userId,
      close: () => stream.close(),
    };

    user.photo.addSSEClient(client);

    await stream.writeSSE({
      data: JSON.stringify({ type: "connected", userId }),
    });

    // Send existing photos
    for (const photo of user.photo.getAllMap().values()) {
      const base64Data = photo.buffer.toString("base64");
      await stream.writeSSE({
        data: JSON.stringify({
          requestId: photo.requestId,
          timestamp: photo.timestamp.getTime(),
          mimeType: photo.mimeType,
          filename: photo.filename,
          size: photo.size,
          userId: photo.userId,
          base64: base64Data,
          dataUrl: `data:${photo.mimeType};base64,${base64Data}`,
          detections: photo.detections ?? null,
          width: photo.width ?? null,
          height: photo.height ?? null,
        }),
      });
    }

    stream.onAbort(() => {
      console.log(`[SSE Photo] Client disconnected for user: ${userId}`);
      user.photo.removeSSEClient(client);
    });

    while (true) {
      await stream.sleep(30000);
    }
  });
}

/** GET /transcription-stream — SSE for real-time transcriptions */
export function transcriptionStream(c: Context) {
  const userId = c.req.query("userId");
  if (!userId) return c.json({ error: "userId is required" }, 400);

  const user = sessions.get(userId);
  if (!user) return c.json({ error: `No user for ${userId}` }, 404);

  console.log(`[SSE Transcription] Client connected for user: ${userId}`);

  return streamSSE(c, async (stream) => {
    const client = {
      write: (data: string) => stream.writeSSE({ data }),
      userId,
      close: () => stream.close(),
    };

    user.transcription.addSSEClient(client);

    await stream.writeSSE({
      data: JSON.stringify({ type: "connected", userId }),
    });

    stream.onAbort(() => {
      console.log(
        `[SSE Transcription] Client disconnected for user: ${userId}`,
      );
      user.transcription.removeSSEClient(client);
    });

    while (true) {
      await stream.sleep(30000);
    }
  });
}

import { AppSession } from "@mentra/sdk";
import { PhotoManager } from "../manager/PhotoManager";
import { TranscriptionManager } from "../manager/TranscriptionManager";
import { AudioManager } from "../manager/AudioManager";
import { StorageManager } from "../manager/StorageManager";
import { InputManager } from "../manager/InputManager";

/**
 * User — per-user state container.
 *
 * Composes all managers and holds the glasses AppSession.
 * Created when a user connects (glasses or webview) and
 * destroyed when the session is cleaned up.
 */
export class User {
  /** Active glasses connection, null when webview-only */
  appSession: AppSession | null = null;

  /** Photo capture, storage, and SSE broadcasting */
  photo: PhotoManager;

  /** Speech-to-text listener and SSE broadcasting */
  transcription: TranscriptionManager;

  /** Text-to-speech and audio control */
  audio: AudioManager;

  /** User preferences via MentraOS Simple Storage */
  storage: StorageManager;

  /** Button presses and touchpad gestures */
  input: InputManager;

  constructor(public readonly userId: string) {
    this.photo = new PhotoManager(this);
    this.transcription = new TranscriptionManager(this);
    this.audio = new AudioManager(this);
    this.storage = new StorageManager(this);
    this.input = new InputManager(this);
  }

  /** Wire up a glasses connection — sets up all event listeners */
  setAppSession(session: AppSession): void {
    this.appSession = session;
    this.transcription.setup(session);
    this.input.setup(session);
    console.log(`📸 Camera ready for ${this.userId}`);
  }

  /** Disconnect glasses but keep user alive (photos, SSE clients stay) */
  clearAppSession(): void {
    this.transcription.destroy();
    this.appSession = null;
  }

  /** Nuke everything — call on full disconnect */
  cleanup(): void {
    this.transcription.destroy();
    this.photo.destroy();
    this.appSession = null;
  }
}

import type { AppSession } from "@mentra/sdk";
import type { User } from "../session/User";

/**
 * All supported touchpad gestures on the glasses.
 */
export const GESTURES = [
  "single_tap",
  "double_tap",
  "triple_tap",
  "long_press",
  "forward_swipe",
  "backward_swipe",
  "up_swipe",
  "down_swipe",
] as const;

export type GestureName = (typeof GESTURES)[number];

/**
 * InputManager — handles all physical input from the glasses (buttons + touchpad).
 *
 * Registers listeners on the AppSession and routes events to the
 * appropriate manager (e.g. single_tap → photo.takePhoto()).
 */
export class InputManager {
  constructor(private user: User) {}

  /** Wire up all button and touch listeners on the glasses session */
  setup(session: AppSession): void {
    this.setupButtons(session);
    this.setupTouch(session);
  }

  /** Button press handlers */
  private setupButtons(session: AppSession): void {
    session.events.onButtonPress(async (button) => {
      console.log(`[Button] ${this.user.userId}: ${button.buttonId} (${button.pressType})`);

      if (button.pressType === "long") {
        // Reserved for future use
        return;
      }

      // Quick press — take a photo
      await this.user.photo.takePhoto();
    });
  }

  /** Touchpad gesture handlers */
  private setupTouch(session: AppSession): void {
    session.events.onTouchEvent("single_tap", async () => {
      console.log(`[Touch] ${this.user.userId}: single_tap`);
      await this.user.photo.takePhoto();
    });

    session.events.onTouchEvent("double_tap", () => {
      console.log(`[Touch] ${this.user.userId}: double_tap — toggle Live Scan`);
      const status = this.user.photo.getLiveScanStatus();
      if (status.active) this.user.photo.stopLiveScan();
      else this.user.photo.startLiveScan();
    });

    session.events.onTouchEvent("triple_tap", () => {
      console.log(`[Touch] ${this.user.userId}: triple_tap`);
    });

    session.events.onTouchEvent("long_press", () => {
      console.log(`[Touch] ${this.user.userId}: long_press`);
    });

    session.events.onTouchEvent("forward_swipe", () => {
      console.log(`[Touch] ${this.user.userId}: forward_swipe`);
    });

    session.events.onTouchEvent("backward_swipe", () => {
      console.log(`[Touch] ${this.user.userId}: backward_swipe`);
    });

    session.events.onTouchEvent("up_swipe", () => {
      console.log(`[Touch] ${this.user.userId}: up_swipe`);
    });

    session.events.onTouchEvent("down_swipe", () => {
      console.log(`[Touch] ${this.user.userId}: down_swipe`);
    });
  }
}

import { User } from "../session/User";

/**
 * SessionManager — thin lookup for User objects.
 *
 * Just a Map<userId, User> with getOrCreate/get/remove.
 * All per-user state lives inside the User class itself.
 */
export class SessionManager {
  private users: Map<string, User> = new Map();

  /** Get an existing user or create a new one */
  getOrCreate(userId: string): User {
    let user = this.users.get(userId);
    if (!user) {
      user = new User(userId);
      this.users.set(userId, user);
      console.log(`[SessionManager] Created user: ${userId}`);
    }
    return user;
  }

  /** Get an existing user (undefined if not found) */
  get(userId: string): User | undefined {
    return this.users.get(userId);
  }

  /** Clean up and remove a user */
  remove(userId: string): void {
    const user = this.users.get(userId);
    if (user) {
      user.cleanup();
      this.users.delete(userId);
      console.log(`[SessionManager] Removed user: ${userId}`);
    }
  }
}

/** Singleton — import this everywhere */
export const sessions = new SessionManager();

/**
 * MentraOS Camera App - Fullstack Entry Point
 *
 * Uses Bun.serve() with HTML imports for the frontend
 * and Hono-based AppServer for the backend + MentraOS SDK.
 */

import { CameraApp } from "./server/CameraApp";
import { api } from "./server/routes/routes";
import { createMentraAuthRoutes } from "@mentra/sdk";
import indexHtml from "./frontend/index.html";
// COMMENTED OUT: YOLO food detection - focusing on basic photo capture first
// import { foodDetector } from "./server/detection/FoodDetector";

// Configuration from environment
const PORT = parseInt(process.env.PORT || "3000", 10);
const PACKAGE_NAME = process.env.PACKAGE_NAME;
const API_KEY = process.env.MENTRAOS_API_KEY;
const COOKIE_SECRET = process.env.COOKIE_SECRET || API_KEY;
const MENTRAOS_WEBSOCKET_URL = process.env.MENTRAOS_WEBSOCKET_URL;
const MENTRAOS_API_URL = process.env.MENTRAOS_API_URL;

// Validate required environment variables
if (!PACKAGE_NAME) {
  console.error("PACKAGE_NAME environment variable is not set");
  process.exit(1);
}

if (!API_KEY) {
  console.error("MENTRAOS_API_KEY environment variable is not set");
  process.exit(1);
}

console.log("📸 Starting Camera App\n");
console.log(`   Package: ${PACKAGE_NAME}`);
console.log(`   Port: ${PORT}`);
console.log(`   MentraOS WebSocket: ${MENTRAOS_WEBSOCKET_URL || 'not set (will use webhook URL)'}`);
console.log(`   MentraOS API: ${MENTRAOS_API_URL || 'not set (will use webhook URL)'}`);
console.log(`   API Key: ${API_KEY ? API_KEY.substring(0, 20) + '...' : 'not set'}`);
console.log("");

// Initialize App (extends Hono via AppServer)
const app = new CameraApp({
  packageName: PACKAGE_NAME,
  apiKey: API_KEY,
  port: PORT,
  cookieSecret: COOKIE_SECRET,
  mentraOSWebsocketUrl: MENTRAOS_WEBSOCKET_URL,
});

// Add webhook logging middleware
app.use("/webhook", async (c, next) => {
  const startTime = Date.now();
  console.log('');
  console.log('━'.repeat(60));
  console.log('🔔 WEBHOOK REQUEST RECEIVED');
  console.log('━'.repeat(60));
  console.log(`   Method: ${c.req.method}`);
  console.log(`   URL: ${c.req.url}`);
  console.log(`   Headers: ${JSON.stringify(Object.fromEntries(c.req.raw.headers), null, 2)}`);

  let bodyData: any = null;
  try {
    bodyData = await c.req.json();
    console.log(`   Body: ${JSON.stringify(bodyData, null, 2)}`);

    // Log specific webhook details
    if (bodyData.type === 'session_request') {
      console.log('');
      console.log('📋 Session Request Details:');
      console.log(`   Session ID: ${bodyData.sessionId}`);
      console.log(`   User ID: ${bodyData.userId}`);
      console.log(`   WebSocket URL: ${bodyData.websocketUrl || bodyData.mentraOSWebsocketUrl || 'not provided'}`);
      console.log(`   Timestamp: ${bodyData.timestamp}`);
    }

    // Put the body back so the handler can read it
    c.req.raw = new Request(c.req.raw, {
      body: JSON.stringify(bodyData),
      headers: c.req.raw.headers,
      method: c.req.raw.method,
    });
  } catch (e) {
    console.log(`   ❌ Body parsing error: ${e}`);
  }

  console.log('');
  console.log('⏳ Processing webhook...');
  console.log('');

  try {
    await next();
  } catch (error: any) {
    console.error('');
    console.error('❌ WEBHOOK PROCESSING ERROR:');
    console.error(`   ${error.message || error}`);
    if (error.stack) {
      console.error(`   Stack: ${error.stack}`);
    }
    console.error('');
    throw error;
  }

  const duration = Date.now() - startTime;
  console.log('');
  console.log('━'.repeat(60));
  console.log('📤 WEBHOOK RESPONSE');
  console.log('━'.repeat(60));
  console.log(`   Status: ${c.res.status}`);
  console.log(`   Duration: ${duration}ms`);

  try {
    const responseClone = c.res.clone();
    const responseBody = await responseClone.text();
    console.log(`   Body: ${responseBody}`);
  } catch (e) {
    console.log(`   Body: (unable to read)`);
  }

  console.log('━'.repeat(60));
  console.log('');
});

// Add middleware to intercept and override cloudApiUrl from URL params
app.use("/api/mentra/auth/*", async (c, next) => {
  console.log('');
  console.log('🔐 AUTH API MIDDLEWARE');
  console.log(`   Request URL: ${c.req.url}`);
  console.log(`   Method: ${c.req.method}`);
  console.log(`   Path: ${c.req.path}`);

  const url = new URL(c.req.url);
  console.log(`   Search params: ${url.search}`);

  // If we have a configured MENTRAOS_API_URL, override any cloudApiUrl params
  if (MENTRAOS_API_URL) {
    console.log(`   MENTRAOS_API_URL is configured: ${MENTRAOS_API_URL}`);

    // Check if cloudApiUrl is in the query params
    if (url.searchParams.has('cloudApiUrl')) {
      const originalUrl = url.searchParams.get('cloudApiUrl');
      console.log(`🔄 Intercepting cloudApiUrl parameter`);
      console.log(`   Original: ${originalUrl}`);
      console.log(`   Overriding with: ${MENTRAOS_API_URL}`);

      // Replace with our zrok tunnel URL
      url.searchParams.set('cloudApiUrl', MENTRAOS_API_URL);

      // Create new request with modified URL
      const newRequest = new Request(url.toString(), c.req.raw);
      c.req.raw = newRequest;
      console.log(`   ✅ Request modified`);
    } else {
      console.log(`   ℹ️  No cloudApiUrl param found in auth request`);
    }
  } else {
    console.log(`   ⚠️  MENTRAOS_API_URL is not configured`);
  }
  console.log('');

  await next();
});

// Mount Mentra auth routes for frontend token exchange
app.route(
  "/api/mentra/auth",
  createMentraAuthRoutes({
    apiKey: API_KEY,
    packageName: PACKAGE_NAME,
    cookieSecret: COOKIE_SECRET || "",
    mentraOSApiUrl: MENTRAOS_API_URL, // Override MentraOS API URL for zrok tunnel
  } as any),
);

// Mount API routes
// @ts-ignore - Hono type compatibility
app.route("/api", api);

// Determine environment
const isDevelopment = process.env.NODE_ENV === "development";

// Start the SDK app (registers SDK routes, checks version)
await app.start();

// COMMENTED OUT: YOLO food detection - focusing on basic photo capture first
// Warm up the YOLO food detector in the background — first inference is slow
// because the ONNX model needs to load. We don't await this so the server can
// start serving immediately; the first photo just waits briefly if needed.
// foodDetector.load().catch((err) => {
//   console.error("⚠️  YOLO food detector failed to warm up:", err);
// });

console.log(`✅ Camera app running at http://localhost:${PORT}`);
console.log(`   • Webview: http://localhost:${PORT}`);
console.log(`   • API: http://localhost:${PORT}/api/health`);
console.log("");

if (isDevelopment) {
  console.log("ℹ️  Development mode - MentraOS desktop app connection is optional");
  console.log("   App will work for web testing without glasses connected");
  if (MENTRAOS_WEBSOCKET_URL) {
    console.log(`   Connecting to: ${MENTRAOS_WEBSOCKET_URL}`);
  }
  console.log("");
}

// Serve static assets
const publicPath = `${process.cwd()}/src/public/assets`;

// Start Bun server with HMR support
Bun.serve({
  port: PORT,
  idleTimeout: 120, // 2 minutes for SSE connections
  development: isDevelopment && {
    hmr: true,
    console: true,
  },
  routes: {
    // Serve the React frontend at root
    "/": indexHtml,
    "/webview": indexHtml,
    "/webview/*": indexHtml,
  },
  fetch(request) {
    const url = new URL(request.url);

    // DEBUG: Log ALL incoming requests to understand what's happening
    console.log('');
    console.log('📍 INCOMING REQUEST');
    console.log(`   Method: ${request.method}`);
    console.log(`   URL: ${url.toString()}`);
    console.log(`   Pathname: ${url.pathname}`);
    console.log(`   Search params: ${url.search}`);
    if (url.searchParams.has('cloudApiUrl')) {
      console.log(`   🔍 HAS cloudApiUrl param: ${url.searchParams.get('cloudApiUrl')}`);
    }
    console.log('');

    // Intercept webview requests and override cloudApiUrl parameter
    if ((url.pathname === "/" || url.pathname.startsWith("/webview")) && MENTRAOS_API_URL) {
      console.log('✅ Webview path detected, checking for cloudApiUrl...');
      if (url.searchParams.has('cloudApiUrl')) {
        const originalUrl = url.searchParams.get('cloudApiUrl');
        console.log('');
        console.log('🌐 Intercepting webview page load');
        console.log(`   Original cloudApiUrl: ${originalUrl}`);
        console.log(`   Overriding with: ${MENTRAOS_API_URL}`);

        // Redirect to same page with corrected cloudApiUrl
        url.searchParams.set('cloudApiUrl', MENTRAOS_API_URL);

        // Also need to update the checksum if present (MentraOS validates it)
        if (url.searchParams.has('cloudApiUrlChecksum')) {
          // Remove checksum to bypass validation - SDK will work without it
          url.searchParams.delete('cloudApiUrlChecksum');
          console.log(`   Removed cloudApiUrlChecksum (will be recalculated if needed)`);
        }

        console.log(`   Redirecting to: ${url.toString()}`);
        console.log('');

        return Response.redirect(url.toString(), 302);
      } else {
        console.log('ℹ️  No cloudApiUrl param in webview request');
      }
    }

    // Serve static assets from /assets/
    if (url.pathname.startsWith("/assets/")) {
      const filePath = `${publicPath}${url.pathname.replace("/assets", "")}`;
      const file = Bun.file(filePath);
      return new Response(file);
    }

    // Handle all other requests through Hono app
    return app.fetch(request);
  },
});

if (isDevelopment) {
  console.log(`🔥 HMR enabled for development`);
}
console.log("");

// Graceful shutdown
const shutdown = async () => {
  console.log("\n🛑 Shutting down Camera App...");
  await app.stop();
  console.log("👋 Goodbye!");
  process.exit(0);
};

process.on("SIGINT", shutdown);
process.on("SIGTERM", shutdown);

