import { useState, useEffect, useCallback, useRef } from "react";
import { Camera, Moon, Sun } from "lucide-react";
import { Badge, Switch } from "../../components/ui";
import { useTheme } from "../../App";
import { PhotoStream, type Photo } from "./components/PhotoStream";
import { SystemLogs, type Log } from "./components/SystemLogs";

interface HomePageProps {
  userId: string;
}

export default function HomePage({ userId }: HomePageProps) {
  const { isDarkMode, toggleTheme } = useTheme();
  const [photos, setPhotos] = useState<Photo[]>([]);
  const [logs, setLogs] = useState<Log[]>([]);
  const logIdCounter = useRef(Date.now());

  const addLog = useCallback((message: string) => {
    setLogs((prev) =>
      [
        {
          id: logIdCounter.current++,
          message,
          time: new Date().toLocaleTimeString(),
        },
        ...prev,
      ].slice(0, 20),
    );
  }, []);

  // Subscribe to the photo SSE stream — every captured photo lands here.
  useEffect(() => {
    let eventSource: EventSource | null = null;
    let connected = false;

    const connect = () => {
      eventSource = new EventSource(
        `/api/photo-stream?userId=${encodeURIComponent(userId)}`,
      );

      eventSource.onopen = () => {
        if (!connected) addLog("Connected to photo stream");
        connected = true;
      };

      eventSource.onmessage = (event) => {
        try {
          const data = JSON.parse(event.data);
          if (data.type === "connected") return;

          const next: Photo = {
            id: data.requestId,
            requestId: data.requestId,
            url: data.dataUrl,
            timestamp: new Date(data.timestamp).toLocaleTimeString(),
            detections: data.detections ?? null,
            width: data.width ?? null,
            height: data.height ?? null,
          };

          setPhotos((prev) => {
            const idx = prev.findIndex((p) => p.requestId === next.requestId);
            if (idx >= 0) {
              const updated = [...prev];
              updated[idx] = next;
              return updated;
            }
            addLog(`Photo captured at ${next.timestamp}`);
            return [next, ...prev].slice(0, 6);
          });
        } catch {}
      };

      eventSource.onerror = () => {
        // Only log a real disconnect, not the brief gap during the SSE
        // handshake. With server heartbeats this should be rare.
        if (connected) {
          addLog("Photo stream disconnected, reconnecting…");
          connected = false;
        }
        eventSource?.close();
        setTimeout(connect, 3000);
      };
    };

    connect();
    return () => eventSource?.close();
  }, [addLog, userId]);

  return (
    <div className="max-w-5xl mx-auto p-4 md:p-6 space-y-4">
      <div className="flex items-center justify-between">
        <div className="flex items-center gap-3">
          <div className="w-9 h-9 rounded-xl bg-primary flex items-center justify-center">
            <Camera className="w-4 h-4 text-primary-foreground" />
          </div>
          <div>
            <h1 className="text-lg font-semibold">Food Scanner</h1>
            <p className="text-xs text-muted-foreground">MentraOS Camera</p>
          </div>
        </div>

        <div className="flex items-center gap-3">
          <Badge variant="outline" className="font-mono text-xs">
            {userId?.substring(0, 8)}...
          </Badge>
          <div className="flex items-center gap-2">
            <Sun className="w-3.5 h-3.5 text-muted-foreground" />
            <Switch checked={isDarkMode} onCheckedChange={toggleTheme} />
            <Moon className="w-3.5 h-3.5 text-muted-foreground" />
          </div>
        </div>
      </div>

      <PhotoStream photos={photos} />

      <SystemLogs logs={logs} />
    </div>
  );
}

