import { useState, useEffect, useCallback, useRef } from "react";
import { Camera, Moon, Sun, AlertTriangle } from "lucide-react";
import { Badge, Button, Switch } from "../../components/ui";
import { useTheme, type AuthDiagnostics } from "../../App";
import { PhotoStream, type Photo } from "./components/PhotoStream";
import { SystemLogs, type Log } from "./components/SystemLogs";

interface HomePageProps {
  userId: string;
  frontendToken?: string;
  isAuthenticated: boolean;
  authError?: string | null;
  /**
   * Snapshot of URL params at page-load (set in App.tsx). Optional so an HMR
   * cache mismatch where an older App.tsx omits the prop doesn't crash the
   * page — we fall back to reading window.location.search live.
   */
  urlParams?: AuthDiagnostics;
}

function readStoredAuth() {
  if (typeof window === "undefined") return { userId: null, token: null };
  try {
    return {
      userId: localStorage.getItem("mentra_user_id"),
      token: localStorage.getItem("mentra_frontend_token"),
    };
  } catch {
    return { userId: null, token: null };
  }
}

function fallbackUrlParams(): AuthDiagnostics {
  if (typeof window === "undefined") {
    return {
      hasSignedUserToken: false,
      hasTempToken: false,
      hasCloudApiUrl: false,
      hasCloudApiUrlChecksum: false,
      rawSearch: "",
      paramKeys: [],
    };
  }
  const p = new URLSearchParams(window.location.search);
  return {
    hasSignedUserToken: p.has("aos_signed_user_token"),
    hasTempToken: p.has("aos_temp_token"),
    hasCloudApiUrl: p.has("cloudApiUrl"),
    hasCloudApiUrlChecksum: p.has("cloudApiUrlChecksum"),
    rawSearch: window.location.search,
    paramKeys: Array.from(p.keys()),
  };
}

export default function HomePage({
  userId,
  frontendToken = "",
  isAuthenticated,
  authError = null,
  urlParams,
}: HomePageProps) {
  const safeUrlParams = urlParams ?? fallbackUrlParams();
  const { isDarkMode, toggleTheme } = useTheme();
  const [photos, setPhotos] = useState<Photo[]>([]);
  const [logs, setLogs] = useState<Log[]>([]);
  const [capturing, setCapturing] = useState(false);
  const [glassesConnected, setGlassesConnected] = useState<boolean | null>(null);
  const logIdCounter = useRef(Date.now());
  const stored = readStoredAuth();

  const addLog = useCallback((message: string) => {
    setLogs((prev) =>
      [
        {
          id: logIdCounter.current++,
          message,
          time: new Date().toLocaleTimeString(),
        },
        ...prev,
      ].slice(0, 20),
    );
  }, []);

  // Manual capture — same pipeline as the glasses single_tap.
  const handleCapture = useCallback(async () => {
    if (capturing) return;
    if (!userId) {
      addLog(
        "Cannot capture: webview is not authenticated. Open this page from the MentraOS app.",
      );
      return;
    }
    setCapturing(true);
    addLog("Requesting photo capture…");
    try {
      const res = await fetch("/api/take-photo", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ userId }),
      });
      if (!res.ok) {
        const err = await res.json().catch(() => ({}));
        addLog(`Capture failed (${res.status}): ${err.error || res.statusText}`);
        if (res.status === 404 || res.status === 409) {
          setGlassesConnected(false);
        }
      } else {
        setGlassesConnected(true);
      }
    } catch (e: any) {
      addLog(`Capture error: ${e?.message || e}`);
    } finally {
      setCapturing(false);
    }
  }, [userId, capturing, addLog]);

  // Subscribe to the photo SSE stream.
  useEffect(() => {
    if (!userId) return;
    let eventSource: EventSource | null = null;
    let connected = false;

    const connect = () => {
      eventSource = new EventSource(
        `/api/photo-stream?userId=${encodeURIComponent(userId)}`,
      );

      eventSource.onopen = () => {
        if (!connected) {
          addLog("Connected to photo stream");
          setGlassesConnected(true);
        }
        connected = true;
      };

      eventSource.onmessage = (event) => {
        try {
          const data = JSON.parse(event.data);
          if (data.type === "connected") return;

          const next: Photo = {
            id: data.requestId,
            requestId: data.requestId,
            url: data.dataUrl,
            timestamp: new Date(data.timestamp).toLocaleTimeString(),
            detections: data.detections ?? null,
            width: data.width ?? null,
            height: data.height ?? null,
          };

          setPhotos((prev) => {
            const idx = prev.findIndex((p) => p.requestId === next.requestId);
            if (idx >= 0) {
              const updated = [...prev];
              updated[idx] = next;
              return updated;
            }
            addLog(`Photo captured at ${next.timestamp}`);
            return [next, ...prev].slice(0, 6);
          });
        } catch {}
      };

      eventSource.onerror = () => {
        if (connected) {
          addLog("Photo stream disconnected, reconnecting…");
          connected = false;
          setGlassesConnected(false);
        }
        eventSource?.close();
        setTimeout(connect, 3000);
      };
    };

    connect();
    return () => eventSource?.close();
  }, [addLog, userId]);

  return (
    <div className="max-w-5xl mx-auto p-4 md:p-6 space-y-4">
      <div className="flex items-center justify-between">
        <div className="flex items-center gap-3">
          <div className="w-9 h-9 rounded-xl bg-primary flex items-center justify-center">
            <Camera className="w-4 h-4 text-primary-foreground" />
          </div>
          <div>
            <h1 className="text-lg font-semibold">Food Scanner</h1>
            <p className="text-xs text-muted-foreground">MentraOS Camera</p>
          </div>
        </div>

        <div className="flex items-center gap-3">
          {userId ? (
            <Badge variant="outline" className="font-mono text-xs">
              {userId.substring(0, 8)}…
            </Badge>
          ) : (
            <Badge variant="destructive" className="text-xs gap-1">
              <AlertTriangle className="w-3 h-3" />
              Not authenticated
            </Badge>
          )}
          {glassesConnected === false && userId && (
            <Badge variant="destructive" className="text-xs gap-1">
              <AlertTriangle className="w-3 h-3" />
              Glasses offline
            </Badge>
          )}
          <div className="flex items-center gap-2">
            <Sun className="w-3.5 h-3.5 text-muted-foreground" />
            <Switch checked={isDarkMode} onCheckedChange={toggleTheme} />
            <Moon className="w-3.5 h-3.5 text-muted-foreground" />
          </div>
        </div>
      </div>

      {!isAuthenticated && (
        <AuthDiagnosticsPanel
          userId={userId}
          frontendToken={frontendToken}
          authError={authError}
          urlParams={urlParams}
          stored={stored}
        />
      )}

      <div className="flex justify-center">
        <Button
          size="lg"
          onClick={handleCapture}
          disabled={capturing}
          className="gap-2"
        >
          <Camera className="w-4 h-4" />
          {capturing ? "Capturing…" : "Capture Photo"}
        </Button>
      </div>

      <PhotoStream photos={photos} />

      <SystemLogs logs={logs} />
    </div>
  );
}

interface AuthDiagPanelProps {
  userId: string;
  frontendToken: string;
  authError: string | null;
  urlParams: AuthDiagnostics;
  stored: { userId: string | null; token: string | null };
}

function AuthDiagnosticsPanel({
  userId,
  frontendToken,
  authError,
  urlParams,
  stored,
}: AuthDiagPanelProps) {
  // Pinpoint the most likely failure mode.
  let diagnosis = "Unknown — check logs in browser DevTools.";
  if (urlParams.paramKeys.length === 0) {
    diagnosis =
      "No auth tokens were present in the page URL. The MentraOS app didn't pass any token — check that the app's Public URL in console.mentra.glass matches the tunnel you're using right now.";
  } else if (urlParams.hasSignedUserToken && authError) {
    diagnosis = `Signed user token was present but verification failed: ${authError}. This usually means the token was signed by a different MentraOS cloud than the one the SDK trusts (prod).`;
  } else if (urlParams.hasSignedUserToken && !userId) {
    diagnosis =
      "Signed user token was present but JWT verification rejected it (likely issuer mismatch — the SDK only trusts https://prod.augmentos.cloud). If you're running a local cloud, that token can't be verified client-side.";
  } else if (urlParams.hasTempToken && !userId) {
    diagnosis =
      "Temp token was present but the /api/mentra/auth/init exchange failed. Check the server log for the auth route — usually a cloudApiUrl mismatch or a bad MENTRAOS_API_URL.";
  } else if (userId && !frontendToken) {
    diagnosis =
      "Got userId but frontendToken is missing. Auth is partial — endpoints needing the token will fail.";
  }

  return (
    <div className="rounded-lg border border-destructive/40 bg-destructive/5 px-4 py-3 text-sm space-y-3">
      <div>
        <p className="font-medium text-destructive">
          Webview not authenticated
        </p>
        <p className="text-xs text-destructive/80 mt-1">{diagnosis}</p>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 gap-3 text-xs font-mono">
        <DiagBlock title="useMentraAuth state">
          <DiagRow label="userId" value={userId || "(empty)"} ok={!!userId} />
          <DiagRow
            label="frontendToken"
            value={frontendToken ? `${frontendToken.substring(0, 12)}…` : "(empty)"}
            ok={!!frontendToken}
          />
          <DiagRow
            label="error"
            value={authError || "(none)"}
            ok={!authError}
          />
        </DiagBlock>

        <DiagBlock title="URL params at load">
          <DiagRow
            label="aos_signed_user_token"
            value={urlParams.hasSignedUserToken ? "present" : "missing"}
            ok={urlParams.hasSignedUserToken}
          />
          <DiagRow
            label="aos_temp_token"
            value={urlParams.hasTempToken ? "present" : "missing"}
            ok={urlParams.hasTempToken}
          />
          <DiagRow
            label="cloudApiUrl"
            value={urlParams.hasCloudApiUrl ? "present" : "missing"}
            ok={urlParams.hasCloudApiUrl}
          />
          <DiagRow
            label="all keys"
            value={urlParams.paramKeys.join(", ") || "(none)"}
            ok={urlParams.paramKeys.length > 0}
          />
        </DiagBlock>

        <DiagBlock title="localStorage">
          <DiagRow
            label="mentra_user_id"
            value={stored.userId || "(empty)"}
            ok={!!stored.userId}
          />
          <DiagRow
            label="mentra_frontend_token"
            value={
              stored.token ? `${stored.token.substring(0, 12)}…` : "(empty)"
            }
            ok={!!stored.token}
          />
        </DiagBlock>
      </div>
    </div>
  );
}

function DiagBlock({
  title,
  children,
}: {
  title: string;
  children: React.ReactNode;
}) {
  return (
    <div className="rounded border border-border/60 bg-background/40 p-2">
      <p className="text-[10px] uppercase tracking-wider text-muted-foreground mb-1.5">
        {title}
      </p>
      <div className="space-y-0.5">{children}</div>
    </div>
  );
}

function DiagRow({
  label,
  value,
  ok,
}: {
  label: string;
  value: string;
  ok: boolean;
}) {
  return (
    <div className="flex justify-between items-baseline gap-2">
      <span className="text-muted-foreground">{label}</span>
      <span className={ok ? "text-foreground" : "text-destructive"} title={value}>
        {value.length > 32 ? `${value.substring(0, 32)}…` : value}
      </span>
    </div>
  );
}

