/**
 * Middleware to validate App API key. Accepts two header shapes:
 *
 *   Authorization: Bearer <packageName>:<apiKey>
 *     Pair is fully validated here; `c.var.sdk` is set with both fields.
 *
 *   Authorization: Bearer <apiKey>
 *     The SDK's webview `exchangeToken` helper sends the bare apiKey and
 *     puts `packageName` in the request body. We parse the apiKey and let
 *     the handler do the pair-validation once it has read the body.
 *     `c.var.sdk` is set with `packageName: ""` to signal "not yet
 *     validated" without changing the AppEnv type.
 */
async function validateAppApiKeyMiddleware(c: AppContext, next: () => Promise<void>) {
  const authHeader = c.req.header("authorization");

  if (!authHeader || !authHeader.startsWith("Bearer ")) {
    return c.json({ error: "Missing or invalid Authorization header" }, 401);
  }

  const token = authHeader.substring(7).trim();
  if (!token) {
    return c.json({ error: "Invalid credentials" }, 401);
  }

  const parts = token.split(":");

  // Pair form: validate now.
  if (parts.length === 2) {
    const [packageName, apiKey] = parts;
    if (!packageName || !apiKey) {
      return c.json({ error: "Invalid credentials" }, 401);
    }
    const { validateApiKey } = await import("../../../services/sdk/sdk.auth.service");
    const isValid = await validateApiKey(packageName, apiKey);
    if (!isValid) {
      return c.json({ error: "Invalid API key" }, 401);
    }
    c.set("sdk", { packageName, apiKey });
    await next();
    return;
  }

  // Bare-apiKey form: defer validation to the handler.
  if (parts.length === 1) {
    c.set("sdk", { packageName: "", apiKey: parts[0] });
    await next();
    return;
  }

  return c.json({ error: "Invalid token format" }, 401);
}

