  console.log(`  publicUrl  = ${after?.publicUrl}`);
  console.log(`  webhookURL = ${after?.webhookURL}`);
  console.log("");
  console.log("Done. Restart any open glasses sessions (relaunch the app on your glasses)");
  console.log("so the cloud reloads the new publicUrl into the in-memory installedApps cache.");

  await mongoose.disconnect();
}

