 * route validates. The SDK refuses to trust a query-string cloudApiUrl
 * unless it is accompanied by a matching checksum: sha256(cloudApiUrl +
 * sha256(apiKey)). Without that, it falls back to https://api.mentra.glass
 * — which makes temp-token exchange fail when running against a non-prod
 * MentraOS cloud.
 */
function computeCloudApiUrlChecksum(cloudApiUrl: string, apiKey: string): string {
  const hashedApiKey = createHash("sha256").update(apiKey).digest("hex");
  return createHash("sha256")
    .update(cloudApiUrl)
    .update(hashedApiKey)
    .digest("hex");
}
// COMMENTED OUT: YOLO food detection - focusing on basic photo capture first
// import { foodDetector } from "./server/detection/FoodDetector";

// Configuration from environment
const PORT = parseInt(process.env.PORT || "3000", 10);
const PACKAGE_NAME = process.env.PACKAGE_NAME;
const API_KEY = process.env.MENTRAOS_API_KEY;
const COOKIE_SECRET = process.env.COOKIE_SECRET || API_KEY;
const MENTRAOS_WEBSOCKET_URL = process.env.MENTRAOS_WEBSOCKET_URL;
const MENTRAOS_API_URL = process.env.MENTRAOS_API_URL;

// Validate required environment variables
if (!PACKAGE_NAME) {
  console.error("PACKAGE_NAME environment variable is not set");
  process.exit(1);
}

if (!API_KEY) {
  console.error("MENTRAOS_API_KEY environment variable is not set");
  process.exit(1);
}

console.log("📸 Starting Camera App\n");
console.log(`   Package: ${PACKAGE_NAME}`);
console.log(`   Port: ${PORT}`);
console.log(`   MentraOS WebSocket: ${MENTRAOS_WEBSOCKET_URL || 'not set (will use webhook URL)'}`);
console.log(`   MentraOS API: ${MENTRAOS_API_URL || 'not set (will use webhook URL)'}`);
console.log(`   API Key: ${API_KEY ? API_KEY.substring(0, 20) + '...' : 'not set'}`);
console.log("");

// Initialize App (extends Hono via AppServer)
const app = new CameraApp({
  packageName: PACKAGE_NAME,
  apiKey: API_KEY,
  port: PORT,
  cookieSecret: COOKIE_SECRET,
  mentraOSWebsocketUrl: MENTRAOS_WEBSOCKET_URL,
});

// Add webhook logging middleware
app.use("/webhook", async (c, next) => {
  const startTime = Date.now();
  console.log('');
  console.log('━'.repeat(60));
  console.log('🔔 WEBHOOK REQUEST RECEIVED');
  console.log('━'.repeat(60));
  console.log(`   Method: ${c.req.method}`);
  console.log(`   URL: ${c.req.url}`);
  console.log(`   Headers: ${JSON.stringify(Object.fromEntries(c.req.raw.headers), null, 2)}`);

  let bodyData: any = null;
  try {
    bodyData = await c.req.json();
    console.log(`   Body: ${JSON.stringify(bodyData, null, 2)}`);

    // Log specific webhook details
    if (bodyData.type === 'session_request') {
      console.log('');
      console.log('📋 Session Request Details:');
      console.log(`   Session ID: ${bodyData.sessionId}`);
      console.log(`   User ID: ${bodyData.userId}`);
      console.log(`   WebSocket URL: ${bodyData.websocketUrl || bodyData.mentraOSWebsocketUrl || 'not provided'}`);
      console.log(`   Timestamp: ${bodyData.timestamp}`);
    }

    // Put the body back so the handler can read it
    c.req.raw = new Request(c.req.raw, {
      body: JSON.stringify(bodyData),
      headers: c.req.raw.headers,
      method: c.req.raw.method,
    });
  } catch (e) {
    console.log(`   ❌ Body parsing error: ${e}`);
  }

  console.log('');
  console.log('⏳ Processing webhook...');
  console.log('');

  try {
    await next();
  } catch (error: any) {
    console.error('');
    console.error('❌ WEBHOOK PROCESSING ERROR:');
    console.error(`   ${error.message || error}`);
    if (error.stack) {
      console.error(`   Stack: ${error.stack}`);
    }
    console.error('');
    throw error;
  }

  const duration = Date.now() - startTime;
  console.log('');
  console.log('━'.repeat(60));
  console.log('📤 WEBHOOK RESPONSE');
  console.log('━'.repeat(60));
  console.log(`   Status: ${c.res.status}`);
  console.log(`   Duration: ${duration}ms`);

  try {
    const responseClone = c.res.clone();
    const responseBody = await responseClone.text();
    console.log(`   Body: ${responseBody}`);
  } catch (e) {
    console.log(`   Body: (unable to read)`);
  }

  console.log('━'.repeat(60));
  console.log('');
});

// Add middleware to intercept and override cloudApiUrl from URL params.
//
// IMPORTANT: The SDK's /api/mentra/auth/init route only trusts a
// `cloudApiUrl` query param if it's accompanied by a matching
// `cloudApiUrlChecksum` (sha256(cloudApiUrl + sha256(apiKey))). When we
// override the URL we *must* recompute the checksum or the SDK will fall
// back to https://api.mentra.glass, and the temp-token exchange fails
// because the token was issued by the user's local cloud.
app.use("/api/mentra/auth/*", async (c, next) => {
  console.log('');
  console.log('🔐 AUTH API MIDDLEWARE');
  console.log(`   Request URL: ${c.req.url}`);
  console.log(`   Method: ${c.req.method}`);
  console.log(`   Path: ${c.req.path}`);

  const url = new URL(c.req.url);
  console.log(`   Search params: ${url.search}`);

  if (MENTRAOS_API_URL) {
    console.log(`   MENTRAOS_API_URL is configured: ${MENTRAOS_API_URL}`);

    if (url.searchParams.has('cloudApiUrl') || url.searchParams.has('aos_temp_token')) {
      const originalUrl = url.searchParams.get('cloudApiUrl');
      console.log(`🔄 Intercepting cloudApiUrl parameter`);
      console.log(`   Original: ${originalUrl ?? '(missing)'}`);
      console.log(`   Overriding with: ${MENTRAOS_API_URL}`);

      url.searchParams.set('cloudApiUrl', MENTRAOS_API_URL);

      // Recompute checksum so the SDK's /init route trusts our override.
      const checksum = computeCloudApiUrlChecksum(MENTRAOS_API_URL, API_KEY!);
      url.searchParams.set('cloudApiUrlChecksum', checksum);
      console.log(`   ✅ Recomputed cloudApiUrlChecksum: ${checksum.substring(0, 16)}…`);

      const newRequest = new Request(url.toString(), c.req.raw);
      c.req.raw = newRequest;
      console.log(`   ✅ Request modified`);
    } else {
      console.log(`   ℹ️  No cloudApiUrl/temp_token param found in auth request`);
    }
  } else {
    console.log(`   ⚠️  MENTRAOS_API_URL is not configured`);
  }
  console.log('');

  await next();
});

// Mount Mentra auth routes for frontend token exchange
app.route(
  "/api/mentra/auth",
  createMentraAuthRoutes({
    apiKey: API_KEY,
    packageName: PACKAGE_NAME,
    cookieSecret: COOKIE_SECRET || "",
    mentraOSApiUrl: MENTRAOS_API_URL, // Override MentraOS API URL for zrok tunnel
  } as any),
);

// Mount API routes
// @ts-ignore - Hono type compatibility
app.route("/api", api);

// Determine environment
const isDevelopment = process.env.NODE_ENV === "development";

// Start the SDK app (registers SDK routes, checks version)
await app.start();

