/**
 * POST a tiny test multipart to `${publicUrl}/photo-upload` and report what
 * comes back. Used inside the photo-timeout error path to disambiguate
 * "tunnel is dead" from "cloud sent the wrong URL".
 *
 * Expected outcome on a healthy tunnel: HTTP 404 with body
 * `{"success":false,"error":"No pending request found for this photo (...)"}`
 * — that's the SDK's `/photo-upload` route correctly bouncing a request
 * with no matching pending photo. Anything else (network error, 5xx,
 * 502 from the tunnel) means the path the glasses use can't reach us.
 */
async function probePhotoUpload(publicUrl: string): Promise<string> {
  const target = `${publicUrl}/photo-upload`;
  const ctrl = new AbortController();
  const t = setTimeout(() => ctrl.abort(), 7000);
  try {
    const form = new FormData();
    form.append("requestId", "self-probe");
    const res = await fetch(target, { method: "POST", body: form, signal: ctrl.signal });
    clearTimeout(t);
    const text = await res.text().catch(() => "");
    const trimmed = text.length > 200 ? `${text.slice(0, 200)}…` : text;
    if (res.status === 404) {
      return `✅ tunnel reachable (HTTP 404 — expected; SDK says "no pending request for this photo")`;
    }
    if (res.status >= 200 && res.status < 300) {
      return `⚠️  HTTP ${res.status} — the route accepted a stub upload, which is unexpected. Body: ${trimmed}`;
    }
    return `❌ HTTP ${res.status} ${res.statusText} — tunnel/server reachable but /photo-upload rejected. Body: ${trimmed}`;
  } catch (err) {
    clearTimeout(t);
    return `❌ unreachable: ${err instanceof Error ? err.message : String(err)} — tunnel down, wrong PUBLIC_URL, or DNS issue`;
  }
}

