import type { User } from "../session/User";
// COMMENTED OUT: YOLO food detection - focusing on basic photo capture first
// import { foodDetector, type Detection } from "../detection/FoodDetector";
type Detection = any; // Placeholder type for now

export interface StoredPhoto {
  requestId: string;
  buffer: Buffer;
  timestamp: Date;
  userId: string;
  mimeType: string;
  filename: string;
  size: number;
