  /** Live Scan state — continuous photo capture pretending to be a video feed. */
  private liveScanActive = false;
  private liveScanIntervalMs = 1200;
  private liveScanLoopPromise: Promise<void> | null = null;
  private liveScanFrames = 0;
  private liveScanStartedAt = 0;
  /** Upper bound on photos kept in memory — important for Live Scan. */
  private static readonly MAX_STORED_PHOTOS = 50;

  constructor(private user: User) {}

  /** Capture a photo from the glasses and store + broadcast it */
  async takePhoto(opts: { size?: "small" | "medium" | "large" | "full"; compress?: "none" | "medium" | "heavy" } = {}): Promise<void> {
    const session = this.user.appSession;
    if (!session) throw new Error("No active glasses session");

    console.log('');
    console.log('📷 REQUESTING PHOTO FROM GLASSES');
    console.log(`   User ID: ${this.user.userId}`);
    console.log(`   Size: ${opts.size || "default"}`);
    console.log(`   Compress: ${opts.compress || "default"}`);
    console.log(`   Session connected: ${!!(session as any).ws}`);
    console.log(`   WebSocket state: ${(session as any).ws?.readyState || "unknown"}`);
    console.log('   ⏳ Calling session.camera.requestPhoto()...');
    console.log('');

    let photo;
    try {
      photo = await session.camera.requestPhoto({
        size: opts.size,
        compress: opts.compress,
        // Make sure the glasses play their built-in shutter sound so the
        // wearer gets immediate audio feedback even if the capture later
        // fails to reach our AppServer.
        sound: true,
      });

      console.log('');
      console.log('✅ PHOTO RECEIVED FROM GLASSES');
      console.log(`   Request ID: ${photo.requestId}`);
      console.log(`   Size: ${photo.size} bytes`);
      console.log(`   MIME type: ${photo.mimeType}`);
      console.log('');
    } catch (err: any) {
      const msg = (err?.message || String(err)).toLowerCase();
      const isTimeout = msg.includes("timed out") || msg.includes("timeout");
      console.error('');
      console.error('❌ PHOTO REQUEST FAILED');
      console.error(`   Error: ${err.message || err}`);
      console.error(`   Error type: ${err.constructor?.name || typeof err}`);

      let probeSummary: string | null = null;
      if (isTimeout) {
        console.error('');
        console.error('   ℹ️  A 30s timeout almost always means the cloud could not POST');
        console.error('       the captured photo back to this AppServer. Check that:');
        console.error('       • Your tunnel (ngrok/zrok) is running and reachable.');
        console.error('       • The "Public URL" in console.mentra.glass for this');
        console.error(`         package (${process.env.PACKAGE_NAME || "<unset>"}) points at that tunnel.`);
        console.error('       • Nothing is blocking POST <PUBLIC_URL>/photo-upload.');

