        // using the configured PUBLIC_URL. This isolates the failure to one
        // of three modes:
        //   ✅ probe ok      → tunnel works → cloud sent the wrong URL or
        //                      photo never left the glasses (check cloud log).
        //   ❌ probe 502/0   → tunnel is broken or zrok share isn't running.
        //   ⚠ no PUBLIC_URL → can't tell; ask the user to set it in .env.
        const publicUrl = (process.env.PUBLIC_URL || "").trim().replace(/\/+$/, "");
        if (publicUrl) {
          probeSummary = await probePhotoUpload(publicUrl);
          console.error('');
          console.error(`   🔎 Self-probe of ${publicUrl}/photo-upload:`);
          console.error(`       ${probeSummary}`);
        } else {
          console.error('');
          console.error('   🔎 Self-probe skipped — set PUBLIC_URL in .env to your tunnel URL');
          console.error('       (e.g. PUBLIC_URL=https://mentrayolo.share.zrok.io) to enable it.');
        }
      }

      if (err.stack) {
        console.error(`   Stack: ${err.stack}`);
      }
      console.error('');
      // Re-throw with a friendlier error for the API surface.
      const baseMsg = isTimeout
        ? "Photo request timed out (30s). The cloud could not deliver the photo to this AppServer — check your public tunnel + console.mentra.glass Public URL."
        : err?.message || String(err);
      throw new Error(probeSummary ? `${baseMsg} Self-probe: ${probeSummary}` : baseMsg);
    }

    const stored: StoredPhoto = {
      requestId: photo.requestId,
      buffer: photo.buffer,
      timestamp: photo.timestamp,
      userId: this.user.userId,
      mimeType: photo.mimeType,
      filename: photo.filename,
