    console.log(
      `📸 Photo captured and broadcast for ${this.user.userId} (${photo.size} bytes, ${this.sseClients.size} SSE client${this.sseClients.size === 1 ? "" : "s"})`,
    );

    // Audible confirmation on the glasses speaker so the wearer knows the
    // capture went through even when the webview isn't in front of them.
    try {
