setupWebhook() {
  const webhookPaths = [this.config.webhookPath || "/webhook", `${SDK_ROUTE_PREFIX}/webhook`];
  const handler = async (c) => {
    try {
      const webhookRequest = await c.req.json();
      if (webhookRequest.type === "session_request" /* SESSION_REQUEST */) {
        return this.handleSessionWebhookRequest(webhookRequest, c);
      } else if (webhookRequest.type === "stop_request" /* STOP_REQUEST */) {
        return this.handleStopWebhookRequest(webhookRequest, c);
      } else {
        this.logger.error("Unknown webhook request type");
        return c.json({
          status: "error",
          message: "Unknown webhook request type"
        }, 400);
      }
    } catch (error) {
      this.logger.error(error, "Error handling webhook");
      return c.json({
        status: "error",
        message: "Error handling webhook: " + error.message
      }, 500);
    }
  };
  for (const path3 of webhookPaths) {
    this.post(path3, handler);
  }
}
setupToolCallEndpoint() {
  const postHandler = async (c) => {
    try {
      const toolCall = await c.req.json();
      toolCall.activeSession = this.getActiveSessionForUser(toolCall.userId);
      this.logger.debug({ toolId: toolCall.toolId }, "Tool call received");
      const response = await this.onToolCall(toolCall);
      if (response !== undefined) {
        return c.json({ status: "success", reply: response });
      } else {
        return c.json({ status: "success", reply: null });
      }
    } catch (error) {
      this.logger.error(error, "Error handling tool call");
      return c.json({
        status: "error",
        message: error instanceof Error ? error.message : "Unknown error occurred calling tool"
      }, 500);
    }
  };
  const getHandler = async (c) => {
    return c.json({ status: "success", reply: "Hello, world!" });
  };
  for (const path3 of ["/tool", `${SDK_ROUTE_PREFIX}/tool`]) {
    this.post(path3, postHandler);
    this.get(path3, getHandler);
  }
}
