import { useState, useEffect, useCallback, createContext, useContext } from "react";
import { useMentraAuth } from "@mentra/react";
import HomePage from "./pages/home/HomePage";

// Theme Context
interface ThemeContextValue {
  theme: "light" | "dark";
  isDarkMode: boolean;
  toggleTheme: () => void;
}

const ThemeContext = createContext<ThemeContextValue>({
  theme: "light",
  isDarkMode: false,
  toggleTheme: () => {},
});

export function useTheme() {
  return useContext(ThemeContext);
}

/**
 * Snapshot the URL params at module load — `MentraAuthProvider` strips
 * them inside its first useEffect, so anything captured later is too late
 * for diagnostics.
 */
export interface AuthDiagnostics {
  hasSignedUserToken: boolean;
  hasTempToken: boolean;
  hasCloudApiUrl: boolean;
  hasCloudApiUrlChecksum: boolean;
  rawSearch: string;
  paramKeys: string[];
}

function snapshotUrlParams(): AuthDiagnostics {
  if (typeof window === "undefined") {
    return {
      hasSignedUserToken: false,
      hasTempToken: false,
      hasCloudApiUrl: false,
      hasCloudApiUrlChecksum: false,
      rawSearch: "",
      paramKeys: [],
    };
  }
  const params = new URLSearchParams(window.location.search);
  return {
    hasSignedUserToken: params.has("aos_signed_user_token"),
    hasTempToken: params.has("aos_temp_token"),
    hasCloudApiUrl: params.has("cloudApiUrl"),
    hasCloudApiUrlChecksum: params.has("cloudApiUrlChecksum"),
    rawSearch: window.location.search,
    paramKeys: Array.from(params.keys()),
  };
}

const INITIAL_URL_PARAMS = snapshotUrlParams();

export default function App() {
  const { userId, frontendToken, isLoading, error, isAuthenticated } =
    useMentraAuth();

  // Theme state with localStorage persistence
  const [theme, setTheme] = useState<"light" | "dark">(() => {
    if (typeof window !== "undefined") {
      const saved = localStorage.getItem("theme");
      if (saved === "dark" || saved === "light") return saved;
    }
    return "light";
  });

  const toggleTheme = useCallback(() => {
    setTheme((prev) => {
      const next = prev === "light" ? "dark" : "light";
      localStorage.setItem("theme", next);
      return next;
    });
  }, []);

  // Apply dark class to document root
  useEffect(() => {
    document.documentElement.classList.toggle("dark", theme === "dark");
  }, [theme]);

  // Sync theme with backend when user authenticates
  useEffect(() => {
    if (isAuthenticated && userId) {
      fetch(`/api/theme-preference?userId=${encodeURIComponent(userId)}`)
        .then((res) => res.json())
        .then((data) => {
          if (data.theme === "dark" || data.theme === "light") {
            setTheme(data.theme);
            localStorage.setItem("theme", data.theme);
          }
        })
        .catch(() => {});
    }
  }, [isAuthenticated, userId]);

  // Save theme to backend on change
  useEffect(() => {
    if (isAuthenticated && userId) {
      fetch("/api/theme-preference", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ userId, theme }),
      }).catch(() => {});
    }
  }, [theme, isAuthenticated, userId]);

  // Keyboard shortcut: Cmd+Shift+D to toggle theme
  useEffect(() => {
    const down = (e: KeyboardEvent) => {
      if (e.key === "d" && (e.metaKey || e.ctrlKey) && e.shiftKey) {
        e.preventDefault();
        toggleTheme();
      }
    };
    document.addEventListener("keydown", down);
    return () => document.removeEventListener("keydown", down);
  }, [toggleTheme]);

  // Loading state
  if (isLoading) {
    return (
      <div className="min-h-screen flex items-center justify-center bg-background">
        <div className="flex flex-col items-center gap-4">
          <div className="animate-spin rounded-full h-8 w-8 border-2 border-muted border-t-foreground" />
          <p className="text-sm text-muted-foreground">Loading...</p>
        </div>
      </div>
    );
  }

  return (
    <ThemeContext.Provider
      value={{ theme, isDarkMode: theme === "dark", toggleTheme }}
    >
      <div className="font-sans bg-background text-foreground min-h-screen">
        <HomePage
          userId={userId || ""}
          frontendToken={frontendToken || ""}
          isAuthenticated={!!isAuthenticated}
          authError={error || null}
          urlParams={INITIAL_URL_PARAMS}
        />
      </div>
    </ThemeContext.Provider>
  );
}

