    console.log('');
    console.log('📷 REQUESTING PHOTO FROM GLASSES');
    console.log(`   User ID: ${this.user.userId}`);
    console.log(`   Size: ${opts.size || "default"}`);
    console.log(`   Compress: ${opts.compress || "default"}`);
    console.log(`   Session connected: ${!!(session as any).ws}`);
    console.log(`   WebSocket state: ${(session as any).ws?.readyState || "unknown"}`);
    console.log('   ⏳ Calling session.camera.requestPhoto()...');
    console.log('');

    let photo;
    try {
      photo = await session.camera.requestPhoto({
        size: opts.size,
        compress: opts.compress,
        // Make sure the glasses play their built-in shutter sound so the
        // wearer gets immediate audio feedback even if the capture later
        // fails to reach our AppServer.
        sound: true,
      });

