      console.error(`   Error: ${err.message || err}`);
      console.error(`   Error type: ${err.constructor?.name || typeof err}`);

      let probeSummary: string | null = null;
      if (isTimeout) {
        console.error('');
        console.error('   ℹ️  A 30s timeout almost always means the cloud could not POST');
        console.error('       the captured photo back to this AppServer. Check that:');
        console.error('       • Your tunnel (ngrok/zrok) is running and reachable.');
        console.error('       • The "Public URL" in console.mentra.glass for this');
        console.error(`         package (${process.env.PACKAGE_NAME || "<unset>"}) points at that tunnel.`);
        console.error('       • Nothing is blocking POST <PUBLIC_URL>/photo-upload.');

        // Inline self-probe: try to reach our own /photo-upload from outside
        // using the configured PUBLIC_URL. This isolates the failure to one
        // of three modes:
        //   ✅ probe ok      → tunnel works → cloud sent the wrong URL or
        //                      photo never left the glasses (check cloud log).
        //   ❌ probe 502/0   → tunnel is broken or zrok share isn't running.
        //   ⚠ no PUBLIC_URL → can't tell; ask the user to set it in .env.
        const publicUrl = (process.env.PUBLIC_URL || "").trim().replace(/\/+$/, "");
        if (publicUrl) {
          probeSummary = await probePhotoUpload(publicUrl);
          console.error('');
          console.error(`   🔎 Self-probe of ${publicUrl}/photo-upload:`);
          console.error(`       ${probeSummary}`);
        } else {
          console.error('');
          console.error('   🔎 Self-probe skipped — set PUBLIC_URL in .env to your tunnel URL');
          console.error('       (e.g. PUBLIC_URL=https://mentrayolo.share.zrok.io) to enable it.');
        }
      }

      if (err.stack) {
        console.error(`   Stack: ${err.stack}`);
      }
      console.error('');
      // Re-throw with a friendlier error for the API surface.
      const baseMsg = isTimeout
        ? "Photo request timed out (30s). The cloud could not deliver the photo to this AppServer — check your public tunnel + console.mentra.glass Public URL."
        : err?.message || String(err);
      throw new Error(probeSummary ? `${baseMsg} Self-probe: ${probeSummary}` : baseMsg);
    }

    const stored: StoredPhoto = {
      requestId: photo.requestId,
      buffer: photo.buffer,
      timestamp: photo.timestamp,
      userId: this.user.userId,
      mimeType: photo.mimeType,
      filename: photo.filename,
      size: photo.size,
      // COMMENTED OUT: YOLO detection features for now
      // detections: undefined,
      // width: undefined,
      // height: undefined,
    };

    this.photos.set(photo.requestId, stored);
    this.evictOldPhotos();

    // Broadcast the photo immediately (no detection processing)
    this.broadcastPhoto(stored);
    console.log(
      `📸 Photo captured and broadcast for ${this.user.userId} (${photo.size} bytes, ${this.sseClients.size} SSE client${this.sseClients.size === 1 ? "" : "s"})`,
    );

    // Audible confirmation on the glasses speaker so the wearer knows the
    // capture went through even when the webview isn't in front of them.
    try {
      await session.audio.speak("Photo captured");
    } catch (err) {
      console.warn(`[Photo] TTS confirmation failed for ${this.user.userId}:`, err);
    }

    // COMMENTED OUT: YOLO food detection - focusing on basic photo capture first
    // this.runDetection(stored).catch((err) => {
    //   console.error(
    //     `[YOLO] Detection failed for ${this.user.userId} / ${photo.requestId}:`,
    //     err,
    //   );
    // });
  }

