/**
 * API Route Definitions
 *
 * Maps HTTP methods + paths to handler functions.
 * Each handler lives in its own file under api/.
 */

import { Hono } from "hono";
import { getHealth } from "../api/health";
import { photoStream, transcriptionStream } from "../api/stream";
import { speak, stopAudio } from "../api/audio";
import { getThemePreference, setThemePreference } from "../api/storage";
import {
  getLatestPhoto,
  getPhotoData,
  getPhotoBase64,
  getPhotoDetections,
  takePhotoNow,
} from "../api/photo";
import { getLiveScanStatus, setLiveScanStatus } from "../api/live-scan";

export const api = new Hono();

// Health
api.get("/health", getHealth);

// SSE streams
api.get("/photo-stream", photoStream);
api.get("/transcription-stream", transcriptionStream);

// Audio
api.post("/speak", speak);
api.post("/stop-audio", stopAudio);

// Storage / preferences
api.get("/theme-preference", getThemePreference);
api.post("/theme-preference", setThemePreference);

// Photos
api.post("/take-photo", takePhotoNow);
api.get("/latest-photo", getLatestPhoto);
api.get("/photo/:requestId", getPhotoData);
api.get("/photo-base64/:requestId", getPhotoBase64);

// Food detections (YOLO11)
api.get("/detections/:requestId", getPhotoDetections);

// Live Scan mode (continuous photo capture for pseudo-live video detection)
api.get("/live-scan", getLiveScanStatus);
api.post("/live-scan", setLiveScanStatus);

import type { Context } from "hono";
import { sessions } from "../manager/SessionManager";

/**
 * POST /take-photo — manually trigger a photo capture.
 * Body: { userId: string }
 *
 * Mirrors the touchpad single_tap path so the webview can drive the same
 * pipeline without depending on the glasses hardware button.
 */
export async function takePhotoNow(c: Context) {
  const body = await c.req.json().catch(() => ({}) as Record<string, unknown>);
  const userId = body.userId as string | undefined;

  if (!userId) return c.json({ error: "userId is required" }, 400);

  const user = sessions.get(userId);
  if (!user) {
    return c.json(
      { error: `No active glasses session for ${userId}` },
      404,
    );
  }
  if (!user.appSession) {
    return c.json(
      { error: "Glasses are not currently connected" },
      409,
    );
  }

  try {
    await user.photo.takePhoto();
    return c.json({ ok: true });
  } catch (err: any) {
    console.error(`[API /take-photo] Failed for ${userId}:`, err);
    return c.json(
      { error: err?.message || "Photo capture failed" },
      500,
    );
  }
}

/** GET /latest-photo — metadata for the most recent photo */
export function getLatestPhoto(c: Context) {
  const userId = c.req.query("userId");

  if (!userId) return c.json({ error: "userId is required" }, 400);

  const user = sessions.get(userId);
  if (!user) return c.json({ error: "No photos available for this user" }, 404);

  const photos = user.photo.getAll();
  if (photos.length === 0) {
    return c.json({ error: "No photos available for this user" }, 404);
  }

  const latest = photos[0];
  return c.json({
    requestId: latest.requestId,
    timestamp: latest.timestamp.getTime(),
    userId: latest.userId,
    hasPhoto: true,
    detections: latest.detections ?? null,
    width: latest.width ?? null,
    height: latest.height ?? null,
  });
}

/** GET /detections/:requestId — YOLO food detections for a specific photo */
export function getPhotoDetections(c: Context) {
  const requestId = c.req.param("requestId");
  const userId = c.req.query("userId");

  if (!userId) return c.json({ error: "userId is required" }, 400);

  const user = sessions.get(userId);
  const photo = user?.photo.getPhoto(requestId);
  if (!photo) return c.json({ error: "Photo not found" }, 404);
  if (photo.userId !== userId) {
    return c.json(
      { error: "Access denied: photo belongs to different user" },
      403,
    );
  }

  return c.json({
    requestId: photo.requestId,
    timestamp: photo.timestamp.getTime(),
    userId: photo.userId,
    width: photo.width ?? null,
    height: photo.height ?? null,
    detections: photo.detections ?? null,
    pending: photo.detections === undefined,
  });
}

/** GET /photo/:requestId — raw photo image data */
export function getPhotoData(c: Context) {
  const requestId = c.req.param("requestId");
  const userId = c.req.query("userId");

  if (!userId) return c.json({ error: "userId is required" }, 400);

  const user = sessions.get(userId);
  const photo = user?.photo.getPhoto(requestId);
  if (!photo) return c.json({ error: "Photo not found" }, 404);
  if (photo.userId !== userId) {
    return c.json(
      { error: "Access denied: photo belongs to different user" },
      403,
    );
  }

  return new Response(new Uint8Array(photo.buffer), {
    headers: {
      "Content-Type": photo.mimeType,
      "Cache-Control": "no-cache",
    },
  });
}

/** GET /photo-base64/:requestId — photo as base64 JSON */
export function getPhotoBase64(c: Context) {
  const requestId = c.req.param("requestId");
  const userId = c.req.query("userId");

  if (!userId) return c.json({ error: "userId is required" }, 400);

  const user = sessions.get(userId);
  const photo = user?.photo.getPhoto(requestId);
  if (!photo) return c.json({ error: "Photo not found" }, 404);
  if (photo.userId !== userId) {
    return c.json(
      { error: "Access denied: photo belongs to different user" },
      403,
    );
  }

  const base64Data = photo.buffer.toString("base64");
  return c.json({
    requestId: photo.requestId,
    timestamp: photo.timestamp.getTime(),
    mimeType: photo.mimeType,
    filename: photo.filename,
    size: photo.size,
    userId: photo.userId,
    base64: base64Data,
    dataUrl: `data:${photo.mimeType};base64,${base64Data}`,
  });
}

