      try {
        this.websocket.close(1001, "App-level pong timeout");
      } catch (err) {
        this.logger.warn({ err }, "[UserSession:appPongTimeout] close failed");
      }
    }
  }, UserSession.APP_LEVEL_PONG_TIMEOUT_MS);
}

